DELIMITER $$
CREATE TRIGGER sc_insert BEFORE INSERT ON sc FOR EACH ROW
BEGIN
IF NOT EXISTS(SELECT 1 FROM student WHERE Sno=NEW.Sno) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='学号不存在'; ELSEIF NOT EXISTS(SELECT 1 FROM course WHERE Cno=NEW.Cno) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='课号不存在'; END IF;
END$$
DELIMITER ;

ALTER TABLE student ADD getcredit INT NOT NULL DEFAULT 0;
DELIMITER $$
CREATE TRIGGER ins_credit AFTER INSERT ON sc FOR EACH ROW
BEGIN
IF NEW.Grade>=60 THEN UPDATE student SET getcredit=getcredit+COALESCE((SELECT Credit FROM course WHERE Cno=NEW.Cno),0) WHERE Sno=NEW.Sno; END IF;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER audit_sc AFTER UPDATE ON sc FOR EACH ROW
BEGIN
IF NOT (OLD.Grade <=> NEW.Grade) THEN INSERT INTO grade_audit VALUES(NEW.Sno,NEW.Cno,OLD.Grade,NEW.Grade); END IF;
END$$
DELIMITER ;
